        properties=(_P_QuantityKindDimensionVector_dimension_exponent_for_mass, _P_QuantityKindDimensionVector_dimension_exponent_for_thermodynamic_temperature, _P_QuantityKindDimensionVector_has_reference_quantity_kind, _P_QuantityKindDimensionVector_dimension_exponent_for_time, _P_QuantityKindDimensionVector_dimension_exponent_for_luminous_intensity, _P_QuantityKindDimensionVector_dimension_exponent_for_amount_of_substance, _P_QuantityKindDimensionVector_dimensionless_exponent, _P_QuantityKindDimensionVector_dimension_exponent_for_length, _P_QuantityKindDimensionVector_latex_definition, _P_QuantityKindDimensionVector_latex_symbol, _P_QuantityKindDimensionVector_dimension_exponent_for_electric_current,),
